import type { ContextAgent, CoverageStatus } from "@selfhost/schema";
import type { ContextItem } from "../types.js";

/**
 * How a generated file names its source:
 * - comment: a comment on the first line (Markdown, plain text, TOML).
 * - front_matter: a YAML comment on the first line inside the front matter, which agents need
 *   at the very top of the file.
 * - block: the marked block selfhost owns inside a TOML file names the source.
 * - lock: the format can't hold a comment (JSON, a skill's scripts and assets); the lock file
 *   lists the file with its source.
 */
export type Header = "comment" | "front_matter" | "block" | "lock";

export type Content =
  | { kind: "text"; text: string }
  | { kind: "bytes"; bytes: Uint8Array; executable: boolean }
  /** One key of a JSON file the agent shares with other settings, like opencode.json's mcp. */
  | { kind: "json_key"; key: string[]; value: unknown }
  /** selfhost's marked block in a TOML file the agent shares with other settings. */
  | { kind: "toml_block"; body: string };

export interface GeneratedFile {
  /** Repository-relative, /-separated. */
  path: string;
  /** Repository-relative source files and folders. */
  sources: string[];
  header: Header;
  content: Content;
}

/** Where one item went for one agent. */
export interface Placement {
  agent: ContextAgent;
  status: Exclude<CoverageStatus, "not_applicable">;
  files: string[];
  detail: string;
}

export const itemId = (item: ContextItem) => `${item.kind}:${item.name}`;

/** The text every header carries, so a file selfhost wrote can be told from a hand-written one. */
export const HEADER_MARK = "Compiled by selfhost from";

/** Names the sources: one file as is, several by their folders. */
export function sourceLabel(sources: readonly string[]): string {
  if (sources.length === 1) return sources[0] as string;
  const folders = [...new Set(sources.map((source) => source.slice(0, source.lastIndexOf("/"))))];
  return folders.length === 1 ? (folders[0] as string) : folders.join(" and ");
}

/** The header sentence. It has no colon, so a naive front matter reader skips it as a comment. */
export function headerText(sources: readonly string[]): string {
  const plural = sources.length > 1 ? "sources" : "source";
  return `${HEADER_MARK} ${sourceLabel(sources)}. Do not edit this file. Change the ${plural}, then run selfhost context compile.`;
}

export const htmlHeader = (sources: readonly string[]) => `<!-- ${headerText(sources)} -->\n`;
export const hashHeader = (sources: readonly string[]) => `# ${headerText(sources)}\n`;

/** True when a file's first lines carry a selfhost header. */
export function hasHeader(text: string): boolean {
  return text.split("\n", 3).some((line) => line.includes(HEADER_MARK));
}

/** Collects the files and placements every kind module produces. */
export class Builder {
  readonly files = new Map<string, GeneratedFile>();
  /** Item ids each file carries, to find the agents that see an item they are not meant for. */
  readonly carries = new Map<string, Set<string>>();
  readonly placements = new Map<string, Placement[]>();

  place(item: ContextItem, placement: Placement): void {
    const id = itemId(item);
    this.placements.set(id, [...(this.placements.get(id) ?? []), placement]);
    for (const file of placement.files) this.carry(file, id);
  }

  carry(path: string, id: string): void {
    const set = this.carries.get(path) ?? new Set<string>();
    set.add(id);
    this.carries.set(path, set);
  }

  /** Adds a file; several agents may add the same file, which must then be identical. */
  add(file: GeneratedFile): void {
    const existing = this.files.get(file.path);
    if (existing && JSON.stringify(existing.content) !== JSON.stringify(file.content)) {
      throw new Error(`two different files compile to ${file.path}`);
    }
    this.files.set(file.path, file);
  }
}

/** A Markdown body with the item's $ARGUMENTS placeholder swapped for another agent's. */
export const withArguments = (body: string, placeholder: string) =>
  body.replaceAll("$ARGUMENTS", placeholder);

/** Control characters TOML strings can't hold as they are (tab and newline can). */
const isControl = (char: string) => {
  const code = char.charCodeAt(0);
  return (code < 0x20 && char !== "\n" && char !== "\t") || code === 0x7f;
};

/** A TOML multi-line string: literal when it can be, else basic with escapes. */
export function tomlMultiline(text: string): string {
  const chars = [...text];
  if (!text.includes("'''") && !chars.some(isControl)) return `'''\n${text}'''`;
  const escaped = chars
    .map((char) =>
      char === "\\"
        ? "\\\\"
        : isControl(char)
          ? `\\u${char.charCodeAt(0).toString(16).padStart(4, "0")}`
          : char,
    )
    .join("")
    .replaceAll('"""', '""\\"');
  return `"""\n${escaped}"""`;
}
